#include <bits/stdc++.h>
#define rep(i,n) for(int i=0; i<(n); i++)
using namespace std;
typedef long long ll;
typedef pair<int,int> pii;

struct Edge { int to, capacity, cost, rev; };

struct MinCostMaxFlow {
    static const int MAXN = 5010;
    vector<Edge> G[MAXN];
    int V;
    int h[MAXN], dist[MAXN], prevv[MAXN], preve[MAXN];

    void init(int n) {
        V = n;
        for (int i=0; i<V; i++) G[i].clear();
    }

    void add_edge(int from, int to, int cap, int cost) {
        G[from].push_back({to, cap, cost, (int)G[to].size()});
        G[to].push_back({from, 0, -cost, (int)G[from].size() - 1});
    }

    int min_cost_flow(int s, int t, int f) {
        int res = 0;
        fill(h, h+V, 0);
        while (f > 0) {
            priority_queue<pii, vector<pii>, greater<pii>> que;
            fill(dist, dist+V, INT_MAX);
            dist[s] = 0;
            que.push({0, s});
            while (!que.empty()) {
                auto [d, v] = que.top(); que.pop();
                if (dist[v] < d) continue;
                for (int i=0; i<(int)G[v].size(); i++) {
                    Edge &e = G[v][i];
                    if (e.capacity > 0 && dist[e.to] > dist[v] + e.cost + h[v] - h[e.to]) {
                        dist[e.to] = dist[v] + e.cost + h[v] - h[e.to];
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        que.push({dist[e.to], e.to});
                    }
                }
            }
            if (dist[t] == INT_MAX) return -1;
            for (int v=0; v<V; v++) h[v] += dist[v];
            int d = f;
            for (int v=t; v!=s; v=prevv[v]) {
                d = min(d, G[prevv[v]][preve[v]].capacity);
            }
            f -= d;
            res += d * h[t];
            for (int v=t; v!=s; v=prevv[v]) {
                Edge &e = G[prevv[v]][preve[v]];
                e.capacity -= d;
                G[v][e.rev].capacity += d;
            }
        }
        return res;
    }
};

int main() {
    int n, m, k, c, d;
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    int a[50], cnt[50] = {0};
    rep(i,k) scanf("%d", a+i);
    rep(i,k) cnt[a[i]-1]++;
    vector<int> e[50];
    rep(i,m) {
        int x, y; scanf("%d%d", &x, &y);
        x--; y--;
        e[x].push_back(y);
        e[y].push_back(x);
    }
    MinCostMaxFlow flow;
    flow.init(n*100+2);
    rep(i,n) flow.add_edge(n*100, i, cnt[i], 0);
    rep(i,100) flow.add_edge(i*n, n*100+1, k, c*i);
    rep(i,n) {
        rep(j,99) flow.add_edge(j*n+i, (j+1)*n+i, k, 0);
        for (int to: e[i]) {
            rep(j,99) {
                rep(u,k) {
                    int cost = (u+1)*(u+1)*d - u*u*d;
                    flow.add_edge(j*n+i, (j+1)*n+to, 1, cost);
                }
            }
        }
    }
    printf("%d\n", flow.min_cost_flow(n*100, n*100+1, k));
}
